import assert from 'node:assert/strict';import {mkdtemp,cp,readFile,writeFile,rm} from 'node:fs/promises';import {tmpdir} from 'node:os';import path from 'node:path';import {chromium} from 'playwright';import {load} from 'cheerio';import {captureSmartSliders} from '../../engine/slider-data.mjs';import {run} from '../../engine/pipeline.mjs';import {serveStatic} from '../../engine/static.mjs';
const root=path.resolve(process.argv[2]||'artifacts/platform/smartslider-installed'),temp=await mkdtemp(path.join(tmpdir(),'smartslider-export-'));let browser,server;
try{
 await cp(path.join(root,'project'),temp,{recursive:true});for(const name of ['component-export.mjs','component-smart-slider.js'])await cp(new URL('../../scripts/'+name,import.meta.url),path.join(temp,'scripts',name));
 const captured=JSON.parse(await readFile(path.join(root,'captured-model.json'),'utf8')),home=captured.pages.find(p=>p.route==='/'),source=load(home.sourceHTML);assert.deepEqual(captureSmartSliders(source),[]);
 const file=path.join(temp,'templates/content/home.html'),$=load(await readFile(file,'utf8'),null,false);source('[data-cloner-smart-slider]').each((_,el)=>{const id=source(el).attr('id');$('[id]').filter((_,e)=>$(e).attr('id')===id).attr('data-cloner-smart-slider',source(el).attr('data-cloner-smart-slider'));});await writeFile(file,$.html());
 await run(process.execPath,['scripts/build.mjs'],{cwd:temp,timeout:120000});server=await serveStatic(path.join(temp,'output'));browser=await chromium.launch({channel:'chrome'});const results=[];
 for(const width of [1440,390]){
  const page=await browser.newPage({viewport:{width,height:900},hasTouch:width<600});page.setDefaultTimeout(12000);const external=[];await page.route('**/*',r=>{if(new URL(r.request().url()).origin===server.url)return r.continue();external.push(r.request().url());return r.abort();});await page.goto(server.url,{waitUntil:'networkidle'});
  const slider=page.locator('[data-cloner-smart-slider-ready=true]');await slider.waitFor();const active=()=>slider.locator('.n2-ss-slide-active').getAttribute('data-slide-public-id');const first=await active();assert.equal(await slider.locator('.n2-ss-slide').count(),3);
  const bounds=await slider.boundingBox();assert.ok(Math.abs(bounds.height-bounds.width/2)<2,'Source image aspect ratio must survive responsive resize');await slider.screenshot({path:path.join(root,'slider-export-'+width+'-first.png')});
  const arrows=await slider.locator('.nextend-arrow-next').isVisible();assert.equal(arrows,width===1440);
  async function swipe(direction){const r=await slider.boundingBox(),cdp=await page.context().newCDPSession(page),start=r.x+r.width*(direction>0?.8:.2),end=r.x+r.width*(direction>0?.2:.8),y=r.y+r.height/2;await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x:start,y}]});for(let i=1;i<=8;i++){await cdp.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[{x:start+(end-start)*i/8,y}]});await page.waitForTimeout(25);}await cdp.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});await cdp.detach();}
  if(arrows)await slider.locator('.nextend-arrow-next').click();else await swipe(1);await page.waitForFunction(first=>document.querySelector('.n2-ss-slide-active').dataset.slidePublicId!==first,first);await page.waitForTimeout(900);await slider.screenshot({path:path.join(root,'slider-export-'+width+'-second.png')});
  if(arrows){await slider.locator('.nextend-arrow-previous').focus();await page.keyboard.press('Enter');}else await swipe(-1);await page.waitForFunction(first=>document.querySelector('.n2-ss-slide-active').dataset.slidePublicId===first,first);
  assert.equal(await slider.locator('.n2-ss-slide:not(.n2-ss-slide-active)').evaluateAll(items=>items.every(el=>el.inert&&el.getAttribute('aria-hidden')==='true')),true);assert.deepEqual(external,[]);results.push({width,slides:3,sourceAspectRatio:true,pointerNext:arrows,keyboardPrevious:arrows,touchBothDirections:!arrows,localAssets:true});await page.close();
 }await writeFile(path.join(root,'slider-export-check.json'),JSON.stringify({results,candidateBuilder:true,scope:'Saved installed image-slider configuration in private native export; broader effects/authoring not yet verified.'},null,2));console.log(JSON.stringify(results));
}finally{await browser?.close();await server?.close();await rm(temp,{recursive:true,force:true});}
